/* Font table, order matches the reader sizes: smallest first. */
static const uint8_t* const reader_fonts[READER_FONT_COUNT] = {
    u8g2_font_4x6_t_cyrillic,
    u8g2_font_5x7_t_cyrillic,
    u8g2_font_7x13_t_cyrillic,
    u8g2_font_10x20_t_cyrillic,
};

static const char* const reader_font_names[READER_FONT_COUNT] = {
    "Tiny",
    "Small",
    "Normal",
    "Large",
};

_Static_assert(COUNT_OF(reader_fonts) == READER_FONT_COUNT, "reader_fonts size mismatch");
_Static_assert(COUNT_OF(reader_font_names) == READER_FONT_COUNT, "reader_font_names size mismatch");

const uint8_t* reader_font_get(size_t size) {
    furi_assert(size < READER_FONT_COUNT);
    return reader_fonts[size];
}

const char* reader_font_name(size_t size) {
    furi_assert(size < READER_FONT_COUNT);
    return reader_font_names[size];
}

size_t reader_font_descender(size_t size) {
    furi_assert(size < READER_FONT_COUNT);
    /* The u8g2 font header keeps the y offset, usually negative, at byte 12. */
    int8_t offset = (int8_t)reader_fonts[size][12];
    return offset < 0 ? (size_t)(-offset) : 0;
}
